template<typename T> 
class MyList{ 
 public: 
 MyList() { this->head = nullptr;} 
 void AddUnique(T val){ 

 if (!head) { 
head = new Node<T>(val); // Add the first element if the list is empty 

return; 
 } 
 Node<T>* temp = head; 
 while (temp) { 
 if (temp->value == val) { 
 return; // Element already exists, do nothing 
 } 
 if (!temp->next) { 
 temp->next = new Node<T>(val); // Add the element at the end of the 
list return; 
 } 
 temp = temp->next; 
 } 
} 

 bool Contains(T val) { 
 for(Node<T>* tmp = head; tmp; tmp = tmp->next) { 
 if (tmp->value == value) { 
 return true; 
 } 
 } 
 return false; 
 } 

 bool remove(T data) { 
 ListElement<T> **p; 
 for (p = &head; *p && data != (*p)->data; p = &((*p)->next)); 
 if (*p) { 
 ListElement<T> *tmp; 
 tmp = *p; 
 *p = (*p)->next; 
 delete tmp; 
 return true; 
 } else { 
 return false; 
 } 
 } 
}; 


3. zadatak 
template <typename T> 
T remove_multiple(Stack<T> &s) { 
 T el1, el2; 
 s.pop(el1); 
 // check if stack is empty 
 if (!s.pop(el2)) { 
 return el2; 
 } 
 s.push(el2); 
 T prev = remove_multiple(s); 
 if (prev != el1) 
 s.push(el1); 
 return el1; 
} 

