template<typename T> 
void insert_bottom(Stack<T>* s, T newEl){ 
 Stack<T> tmp; 
 T el; 
 while(s->Pop(el)){ 
 tmp.Push(el); 
 } 
 s->Push(newEl); 
 while(tmp.Pop(el)){ 
 s->Push(el); 
 } 
} 

