2. zadatak: 
a) 
Ako za svaki A[i] vrijedi A[i] > max, tada je složenost n ∙ (Θ(n – i) + Θ(i) + Θ(1)) = n ∙ Θ(n) = Θ(n2) 
Ako za svaki A[i] vrijedi A[i] <= max, tada je složenost n ∙ log5n ∙ Θ(n) = Θ(n2log n) 

Konačno, uzimajući u obzir sve slučajeve za funkciju f vrijedi: Ω(n2) i O(n2 ∙ logn) 

b) 
T(0) = T(1) = Θ(1), 
T(2) = T(1) + T(1) + Θ(1) = 2T(1) + Θ(1) 
T(3) = T(2) + T(2) + Θ(1) = 4T(1) + 2∙Θ(1) + Θ(1) = 7 ∙ Θ(1) 
T(4) = T(3) + T(3) + Θ(1) = 14 ∙ Θ(1) + Θ(1) = 15 ∙ Θ(1) 
… 
T(k) = T(k - 1) + T(k-1) + Θ(1) = 2 ∙ (2k-1 ∙ Θ(1) - Θ(1)) + Θ(1) = 2k ∙ Θ(1) - Θ(1) = Θ(2k) 

3. zadatak 
template<typename T> 
class MyList{ 
 private: 
 ListElement<T> *head; 
 void PrintRecInternal(ListElement<T> *currHead){ 
 if(currHead == nullptr) return; 
 cout << currHead->item << " "; 
 PrintRecInternal(currHead->next); 
 } 
 public: 
 MyList() { this->head = nullptr;} 
 void AddSorted(T el){ 
 ListElement<T> *elem = new ListElement<T>(el); 
 elem->next = nullptr; 
 if(this->head == nullptr){ 
 this->head = elem; 
 return; 
 } 
 if(this->head->item > el){ 
 elem ->next = head; 
 head = elem; 
 return; 


 } 
 ListElement<T> *p = this->head; 
 ListElement<T> *pp = this->head->next; 
 while(pp && pp->item < el){ 
 p = pp; 
 pp = pp->next; 
 } 
 if(pp == nullptr) { 
 p->next = elem; 
 } 
 else{ 
 elem->next = pp; 
 p->next = elem; 
 } 
 } 

 void AddSorted2(T el){ 
 ListElement<T> *elem = new ListElement<T>(el); 
 elem->next = nullptr; 
 ListElement<T> **p; 
 p = &this->head; 
 while(*p && (*p)->item < el){ 
 p = &((*p)->next); 
 } 
 if(*p == nullptr){ 
 *p = elem; 
 } 
 else{ 
 elem->next = *p; 
 *p = elem; 
 } 
 } 

void Print(){ 
 PrintRecInternal(this->head); 
 } 

void Print2(){ 
 for (ListElement<T> *p = head; p != nullptr; p = p->next) { 
 cout << p->item << " "; 
 } 
 } 

 ~MyList() { 
 ListElement<T> *pom = this->head; 
 while(pom != nullptr){ 
 ListElement<T> *pom2 = pom->next; 
 delete(pom); 
 pom = pom2; 
 } 
 } 
}; 













