template<typename T> 
Stack<T>* copy_reverse(Stack<T>& s){ 
 T el; 
 if(s.Pop(el)){ 
 Stack<T>* o = copy_reverse(s); 
 insert_bottom(o, el); 
 s.Push(el); 
 return o; 
 } 
 else{ 
 Stack<T>* o = new Stack<T>(); 
 return o; 
 } 
} 


