template<typename T> 
class ListElement{ 
 public: 
 T val; 
 ListElement<T>* next; 
 ListElement<T>* prev; 
}; 

template<typename T> 
class DoubleList{ 
 public: 
 ListElement<T>* head; 
 ListElement<T>* tail; 
 DoubleList() {this->head = nullptr; this->tail=nullptr;} 

void AddFirst(T val){ 
 ListElement<T>* newElem = new ListElement<T>(); 
 newElem->val = val; 
 newElem->next = this->head; 
 if(this->head != nullptr) this->head->prev = newElem; 
 newElem->prev = nullptr; 
 this->head = newElem; 
 if(this->tail == nullptr) this->tail = newElem; 
 return; 
 } 
 bool Find(T val){ 
 ListElement<T>* tmp = head; 
 while(tmp){ 
 if(tmp->val == val) return true; 
 tmp = tmp->next; 
 } 
 return false; 
 } 
 ~List(){ 
 while(head){ 
 ListElement<T>* tmp = head->next; 
 delete head; 
 head = tmp; 
 } 

 tail = nullptr; 
 } 
}; 

