Zadana je tablica raspršenog adresiranja s 8472 zapisa pohranjena u datoteci 
"podaci.dat" koja sadrži zapise definirane strukturom 
typedef struct { 

int sifra; 

//šifra studenta 

char prezimeIme[70+1]; //Prezime i ime studenta 

int logickiObrisan; 
//Je li zapis logički obrisan 
} zapis; 
Zapis je prazan ako je sifra = 0. Zapis je logički obrisan ako je logickiObrisan = 1. 
Preljevi su realizirani ciklički, upisom u prvi sljedeći slobodni pretinac. Pretinci su 
usklađeni s veličinom bloka od 512 okteta. Hash-tablica predimenzionirana je za 30%. 
Neka je ključ šifra studenta. Transformacija ključa u adresu obavlja se zadanom 
funkcijom int adresa (int sifra). Napišite pretprocesorske direktive #define 
kojima se određuju parametri raspršenog adresiranja. 
a) Napišite funkciju za logičko brisanje zapisa. Funkcija vraća 1 ako je pronašla i 
obrisala zapis a 0 inače. Funkcija ima prototip: 

int brisi(int sifra, FILE *f) 
b) Napišite funkciju za dodavanje zapisa koja će zapis upisati na mjesto prvog 
praznog zapisa ili logički obrisanog zapisa u pretincu. Funkcija vraća 1 ako je 
uspješno dodala zapis a 0 inače. Funkcija ima prototip: 

int upisi(int sifra, zapis novi, FILE *f)

Zadano je polje brojeva s elementima: 9, 6, 7, 2, 1, 8, 4, 5, 0, 3. Ilustrirajte uzlazno 
sortiranje zadanog niza brojeva (ispišite polje nakon svake promjene i označite sve 
brojeve relevantne za sljedeći korak) algoritmom mergesort i algoritmom shellsort za 
niz koraka {4,3,1}. 

Rješenja 
1. zadatak 
#define BLOK 512L 






#define N 8472 


#define C ((int) (BLOK / sizeof (zapis))) 
#define M ((int) (N / C *1.3)) 



typedef struct { 

int sifra; 

char prezimeIme[70+1]; 

int logickiObrisan; 
} zapis; 

int brisi(int sifra, FILE *f){ 

zapis pretinac [C]; 

int i = 0, poc = 0; 

int adr = adresa(sifra); 

poc = adr; 

do{ 


//Procitaj pretinac odredjen sa adresom 


fseek(f, adr * BLOK, SEEK_SET); 


fread (pretinac, sizeof (pretinac), 1, f); 


//Provjeri zapise u pretincu 


for(i=0; i<C; i++){ 



if(pretinac[i].sifra == sifra){ 




pretinac[i].logickiObrisan = 1; 




//Upis 




fseek(f, -1 * BLOK, SEEK_CUR); 




fwrite (pretinac, sizeof (pretinac), 1, f); 




return 1; 



} 


} 


//Pretinac je pun, prijeđi ciklički na sljedećega 


adr = (adr + 1) % M; 

} while(adr != poc); 

return 0; 
} 

int upisi(int sifra, zapis novi, FILE *f){ 

zapis pretinac [C]; 

int i = 0, poc = 0; 

int adr = adresa(sifra); 

poc = adr; 

do{ 


//Procitaj pretinac odredjen sa adresom 


fseek(f, adr * BLOK, SEEK_SET); 


fread (pretinac, sizeof (pretinac), 1, f); 


for(i=0; i<C; i++){ 



if(pretinac[i].sifra == 0 || 




pretinac[i].logickiObrisan == 1){ 




//Zapis je prazan ili je logicki obrisan 




pretinac[i] = novi; 




//Upis 




fseek(f, -1 * BLOK, SEEK_CUR); 




fwrite (pretinac, sizeof (pretinac), 1, f); 




return 1; 



} 


} 



//Pretinac je pun, prijeđi ciklički na sljedećega 


adr = (adr + 1) % M; 

} while(adr != poc); 

return 0; 
} 



