int *izbaci_podprosj(int *polje, int *br_clanova){ 
int i, j, suma=0; 
float prosjek; 
for (i=0;i<*br_clanova;i++){ 
suma+=polje[i]; 
} 
prosjek= (float) suma/ *br_clanova; 
for(i=0 ; i<*br_clanova ;){ 
if (polje[i] < prosjek){ 
for(j=i+1 ; j<*br_clanova ; j++) 

polje[j-1] = polje[j]; 
(*br_clanova)--; 
} 
else 
i++; 
} 
polje = (int*) realloc(polje, *br_clanova * sizeof(int)); 
return polje; 
} 

