// Pomoćni funkcijski član (protected): 

bool odrediPut(shared_ptr<Cvor>& cvor, Stog<T>& put, const T& el) { 
 if (cvor) { 
 if (cvor->elem == el) { // pronadjen je element cime je put okoncan 
 put.dodaj(el); // prvi element koji se dodaje u put 
 return true; 
 } 
 // provjeri je li element u lijevom ili desnom podstablu 
 else if (odrediPut(cvor->lijevo, put, el) || odrediPut(cvor->desno, put, el)) { 
 // ako je cvor na putu do elementa, dodaj njegovu vrijednost u put 
 put.dodaj(cvor->elem); 
 return true; 
 } 
 } 
 return false; 
} 

