 int h1 = HashDoubleHashing1(key); 
 int h2 = HashDoubleHashing2(key); 
 int index = (h1 + 0 * h2) % this->size; 
 cout << index << " " << i << std::endl; 


 if (index == i) { 
 //element in its position 
 } 
 else{ 
 sum += (i - index + this->size) % this->size; 
 n++; 
 } 
 } 
 } 
 return (float)sum / n; 
 } 
}; 

