#include <stdio.h>
#include <stdlib.h>
#include <math.h>
/*STOG STATICKIM POLJEM*/
typedef struct {
int vrh, polje[MAXSTOG];
}Stog;
void init_stog (Stog *stog) {
/*inicijalizacija*/
stog->vrh = -1;
}
int dodaj (int element, Stog *stog) {
/*dodavanje elementa*/
if (stog->vrh >= MAXSTOG -1) return 0;
stog->vrh++;
stog->polje [stog->vrh] = element;
return 1;
}
int skini (int *element, Stog *stog) {
/*skidanje elementa*/
if (stog->vrh <0) return 0;
*element = stog->polje[stog->vrh];
stog->vrh--;
return 1;
}
/*STOG LISTOM*/
struct at {
int element;
struct at *sljed;
};
typedef struct at atom;
typedef struct {
atom *vrh;
}Stog;
void init_stog (Stog *stog) {
/*inicijalizacija*/
stog->vrh = NULL;
}
int dodaj (int element, Stog *stog) {
/*dodavanje elementa na stog*/
atom *novi;
if ((novi = (atom *)malloc(sizeof(atom)))!=NULL) {
novi->element = element;

novi->sljed = stog->vrh;
stog->vrh = novi;
return 1;
}
else return 0;
}
int skini (int *element, Stog *stog) {
/*skidanje elementa sa stoga*/
atom *pom;
if (stog->vrh == NULL) return 0;
*element = stog->vrh->element;
pom = stog->vrh->sljed;
free(stog->vrh);
stog->vrh = pom;
return 1;
}
/*RED STATICKIM POLJEM*/
typedef struct {
int polje[MAXRED];
int ulaz, izlaz;
} Red;
int dodaj (int element, Red *red) {
/*dodavanje elementa u red*/
if ((red->ulaz+1)%MAXRED == red->izlaz) return 0;
red->ulaz++;
red->ulaz %= MAXRED;
red->polje[red->ulaz] = element;
return 1;
}
int skini (int *element, Red *red) {
/*skidanje elementa s reda*/
if (red->ulaz == red->izlaz) return 0;
red->izlaz++;
red->izlaz %= MAXRED;
*element = red->polje[red->izlaz];
return 1;
}
/*RED LISTOM*/
struct re {
int element;
struct re* sljed;
};
typedef struct re Red;
void init_red (Red *red) {
/*inicijalizacija*/
red->ulaz = NULL;

red->izlaz = NULL;
}
int dodaj (int element, Red *red) {
/*dodavanje elementa u red*/
atom *novi;
if (novi=malloc(sizeof(atom))) {
novi->element = element;
novi->sljed = NULL;
if (red->izlaz == NULL) red->izlaz = novi;
else (red->ulaz)->sljed = novi;
red->ulaz = novi;
return 1;
}
return 0;
}
int skini (int *element, Red *red) {
/*skidanje elementa s reda*/
atom *stari;
if (red->izlaz) {
*element = red->izlaz->element;
stari = red->izlaz;
red->izlaz = red->izlaz->sljed;
free(stari);
if (red->izlaz == NULL) red->ulaz = NULL;
return 1;
}
return 0;
}
