}
/*STABLO*/
struct cv {
int podatak;
struct cvor *lijevo_dijete;
struct cvor *desno_dijete;
struct cvor *roditelj;

};
typedef struct cv cvor;
cvor *dodaj (cvor *cvor, int element) {
/*dodavanje elementa*/
if (cvor == NULL) {
return (NoviCvor(element));
}
else {
if (element <= cvor->podatak)
cvor->lijevo = dodaj(cvor->lijevo_dijete, element);
else 
cvor->desno_dijete = dodaj(cvor->desno_dijete);
return (cvor);
}
}
cvor *NoviCvor (int element) {
/*stvaranje novog cvora*/
cvor* novi = (cvor *)malloc(sizeof(cvor));
novi->podatak = element;
novi->lijevo_dijete= NULL;
novi->desno_dijete = NULL;
return (novi);
}
int trazi (cvor *cvor, int trazeno) {
/*pretrazivanje stabla*/
if (cvor == NULL) return 0;
else {
if (trazeno == cvor->podatak) return 1;
else {
if (trazeno < cvor->podatak) return (trazi(cvor->lijevo_dijete, trazeno)))
else return (trazi(cvor->desno_dijete, trazeno));
}
}
}
/*GOMILA*/
void podesi (int A[], int i, int n) {
/*podesavanje gomile*/
 int j; 
 int stavka;
 j = 2*i;
 stavka = A[i];
 while (j <= n ) {
 if ((j < n) && (A[j] < A[j+1])) j++;
 if (stavka >= A[j]) break;
 A[j/2] = A[j];
 j *=2;
 }
 A[j/2] = stavka; 

}


 void StvoriGomilu (int A[], int n) {
/*stvaranje gomile*/
 int i;
 for (i = n/2; i >= 1; i--) 
podesi (A, i, n);
}
void HeapSort (int A[], int n) {
/*heap sort algoritam*/
 int i;
 StvoriGomilu (A, n);
 for (i = n; i >= 2; i--) {
Zamijeni (&A[1], &A[i]);
 Podesi (A, 1, i-1);
 }
}

