void izbaci(Stog *stog) { 
Stog s1, s2; 
int el, x, nadjen; 


init_stog(&s1); 

init_stog(&s2); 

while(skini(stog, &el)) { 


nadjen = 0; 


while(skini(&s1, &x)) 


{ 



dodaj(&s2, x); 



if (x == el) nadjen = 1; 


} 


if (!nadjen) dodaj(&s2, el); 


while(skini(&s2, &x)) dodaj(&s1, x); 

} 

while(skini(&s1, &x)) dodaj(&s2, x); 

while(skini(&s2, &x)) dodaj(stog, x); 
} 

ILI 

void izbaci(Stog *stog) { 
Stog s1, s2; 
int el, x; 


init_stog(&s1); 

init_stog(&s2); 

while(skini(stog, &el)) { 


dodaj(&s1, el); 


while(skini(stog, &x)) if (x != el) dodaj(&s2, x); 


while(skini(&s2, &x)) dodaj(stog, x); 

} 

while(skini(&s1, &el)) dodaj(stog, el); 
}

