atom *okreniListu(atom *glava) 
{ 

atom *novi, *pom; 

pom = NULL; 

while(glava != NULL) 

{ 


novi = (atom *) malloc(sizeof(atom)); 



novi->element.prosjek = glava->element.prosjek; 


strcpy(novi->element.imeprezime,glava->element.imeprezime); 

