 atom *novi, *p, *zap=NULL, *preth; 
 novi=NULL; 
 for (p = *glava; p; p = p->sljed){ 


suma+=p->element.ocjena; 


brojac++; 
 } 
 if (brojac==0) return novi; 
 prosjek=suma/brojac; 
 for (p = *glava; p; p = p->sljed){ 

 if (p->element.ocjena>=prosjek) { 


 if (novi==NULL) 


 novi=p; 


 else 



 zap->sljed=p; 


 zap=p; 


 if (p==*glava) 



 *glava = (*glava)->sljed; 


 else{ 



preth->sljed=p->sljed; 



p=preth; 


 } 

 } 

 preth=p; 
 } 
 if (zap) zap->sljed=NULL; 
 return novi; 
} 


