4. zadatak 
#include <stdio.h> 
#include <math.h> 

const float PI=3.14; 

class Kugla 
{ 
private: 

float polumjer, gustoca; 

public: 

void SetPolumjer(float polumjer) 

{ 


this->polumjer=polumjer; 

} 

float GetPolumjer() 

{ 


return polumjer; 

} 

void SetGustoca(float gustoca) 

{ 


this->gustoca=gustoca; 

} 

float GetGustoca() 

{ 


return gustoca; 

} 


float volumen() 

{ 


return 4./3*pow(polumjer,3)*PI; 


} 


float masa(){ 



return volumen()*gustoca; 

} 
}; 

int main(){ 

Kugla k1; 

Kugla *k2= new Kugla(); 

k1.SetGustoca(2.1); 

k1.SetPolumjer(3); 

k2->SetGustoca(11.9); 

k2->SetPolumjer(8); 

printf("kugla 1:\n radijus=%f\ngustoca=%f\nvolumen=%f\nmasa=%f\n", 
k1.GetPolumjer(),k1.GetGustoca(),k1.volumen(),k1.masa()); 

printf("kugla 2:\n radijus=%f\ngustoca=%f\nvolumen=%f\nmasa=%f\n", 
k2->GetPolumjer(),k2->GetGustoca(),k2->volumen(),k2->masa()); 

delete k2; 

return 0; 
} 


Ponovljeni završni ispit iz predmeta

Neka je binarno sortirano stablo zadano strukturom: 

struct cv { 
 int broj; 
 struct cv *lijevo; 
 struct cv *desno; 
}; 

typedef struct cv cvor; 

a) (4 boda) Napišite funkciju koja će izračunati sumu svih brojeva u onim čvorovima koji nisu listovi. 
Napišite primjer poziva napisane funkcije. 
b) (4 boda) Napišite funkciju koja će u binarno sortirano stablo ubaciti novi broj. Ako navedeni broj već 
postoji u stablu, novi se čvor ne ubacuje. Napišite primjer poziva napisane funkcije.

Objektno orijentirana implementacija reda zadana je klasom: 

typedef int tip; 
struct at { 


tip element; 


struct at *sljed; 

}; 
typedef struct at atom; 

class Red { 


atom *ulaz, *izlaz; 

void obrisiRed(); 
 public: 

Red(); 

~Red(); 
 int Dodaj (tip element); 
 int Skini (tip *element); 
}; 

Objektno orijentirana implementacija stoga zadana je klasom: 

class Stog{ 



atom *vrh; 

void obrisiStog(); 
 public: 

Stog(); 

~Stog(); 

int Dodaj (tip element); 

int Skini (tip *element); 
}; 

Proširite navedene implementacije odgovarajućim konstruktorima ili funkcijama kako bi bilo moguće 
realizirati sljedeće podebljano označene retke: 

Red red; int n; 

… 
Stog stog(&red, n); /* 
Stvara stog koji sadrži prvih n elemenata iz 
reda (ili sve elemente reda ako on sadrži manje 
od n elemenata). Prvi element iz reda ide na 
dno stoga. Sadržaj reda mora biti očuvan. */ 

Red *noviRed = stog.URed(n); /* 
Vraća pokazivač na novi red koji se 
sastoji od prvih (gornjih) n elemenata stoga 
(ili od svih elemenata stoga ako on sadrži 
manje od n elemenata) Prvi element u redu je 
onaj koji je bio na vrhu stoga. Sadržaj stoga 
mora biti očuvan. */ 

Napomena: prazni konstruktor, destruktor te funkcije Dodaj i Skini već su napisani i njih ne treba pisati. 
(Naravno, smijete ih koristiti!) 

