void ubaci(int element, int gomila[], int n) { 
 int i, pom, novi; 
 n = n+1; 
 novi = element; 
 i = n/2; 
 while ((i > 0) && (gomila[i] < novi)) { 
 gomila[n] = gomila[i]; 
 n = i; 
 i = i/2; 

 } 
 gomila[n] = novi; 
} 

